'use strict';
const daily={values:new Map(),busy:false,updated:'',failed:0};
function dayKey(d){return d.toISOString().slice(0,10);}
function reportBucket(date,mode){if(mode==='month')return date.slice(0,7);if(mode==='week'){const d=new Date(date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+6)%7);return dayKey(d);}return date;}
async function loadDaily(){if(daily.busy)return;daily.busy=true;setLoad('daily','loading','Memuat arsip harian…');try{const index=await json(API+'arsip/index.json');const dates=(index.hotspot||[]).filter(d=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&d<=wibISO().slice(0,10)).sort();const months=[...new Set(dates.map(d=>d.slice(0,7)))].slice(-4);if(!months.length)throw Error('Arsip belum tersedia');const results=await Promise.allSettled(months.map(m=>json(API+'arsip/ringkasan/harian-'+m+'.json')));daily.values.clear();daily.failed=0;results.forEach((r,i)=>{if(r.status==='rejected'){daily.failed++;return;}for(const [date,v] of Object.entries(r.value)){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>wibISO().slice(0,10)||!date.startsWith(months[i]))continue;const pairs=Object.entries(v.kab||{}),entry=pairs.find(([name])=>normalizeKab(name)==='pulang pisau');daily.values.set(date,v.kab?entry&&Number.isFinite(entry[1])?entry[1]:entry?null:0:null);}});const included=dates.filter(d=>months.includes(d.slice(0,7)));daily.min=included[0];daily.max=included.at(-1);daily.updated=index.diperbarui||'';for(const id of ['dailyFrom','dailyTo']){$(id).min=daily.min;$(id).max=daily.max;}if(!$('dailyFrom').value){const start=new Date(daily.max+'T00:00:00Z');start.setUTCDate(start.getUTCDate()-29);$('dailyFrom').value=dayKey(start)<daily.min?daily.min:dayKey(start);$('dailyTo').value=daily.max;}renderDaily();setLoad('daily',daily.failed?'error':'ready','Sebagian arsip belum tersedia.');}catch{$('dailyStatus').textContent='Arsip harian belum dapat dimuat. Klik Perbarui data untuk mencoba kembali.';$('dailyTotal').textContent='Tidak tersedia';$('dailyChart').replaceChildren();setLoad('daily','error','Arsip harian gagal dimuat.');}finally{daily.busy=false;}}
function reportSeries(from,to,mode,values){const buckets=new Map();for(let d=new Date(from+'T00:00:00Z');dayKey(d)<=to;d.setUTCDate(d.getUTCDate()+1)){const date=dayKey(d),key=reportBucket(date,mode);if(!buckets.has(key))buckets.set(key,{key,total:0,days:0,available:0});const b=buckets.get(key),n=values.get(date);b.days++;if(Number.isFinite(n)){b.total+=n;b.available++;}}return [...buckets.values()];}
function renderDaily(){const from=$('dailyFrom').value,to=$('dailyTo').value;if(!from||!to||from>to||from<daily.min||to>daily.max){$('dailyStatus').textContent='Pilih rentang tanggal yang valid dalam cakupan arsip.';$('dailyChart').replaceChildren();$('dailyTotal').textContent='—';return;}const mode=$('dailyGran').value,series=reportSeries(from,to,mode,daily.values),sum=series.reduce((n,b)=>n+b.total,0),available=series.reduce((n,b)=>n+b.available,0),days=series.reduce((n,b)=>n+b.days,0);$('dailyTotal').textContent=available?fmt(sum)+' deteksi'+(available<days?' · parsial':''):'Data tidak tersedia';$('dailyStatus').textContent=`${from} hingga ${to} · ${available}/${days} hari tersedia. `+(mode==='week'?'Minggu dimulai Senin; tepi rentang dapat berupa sebagian minggu. ':'')+'Arsip diperbarui: '+(daily.updated?wib(new Date(daily.updated)):'waktu tidak tersedia')+(daily.failed?' · sebagian arsip gagal dimuat.':'');const max=Math.max(1,...series.map(b=>b.total)),W=Math.max(320,Math.round($('dailyChart').clientWidth||680)),H=240,pad=42,base=194,slot=(W-pad-15)/series.length;let svg=`<svg viewBox="0 0 ${W} ${H}" role="group" aria-label="Grafik deteksi titik panas Pulang Pisau, ${esc(from)} sampai ${esc(to)}">`;for(let i=0;i<=4;i++){const y=base-i*40;svg+=`<line x1="${pad}" y1="${y}" x2="${W-10}" y2="${y}" stroke="#e3e9df"/><text x="4" y="${y+4}">${fmt(max*i/4)}</text>`;}series.forEach((b,i)=>{const x=pad+i*slot+slot*.16,height=b.available?160*b.total/max:4;svg+=`<rect x="${x}" y="${base-height}" width="${slot*.68}" height="${Math.max(2,height)}" rx="2" fill="${!b.available?'#c4c9c4':b.available<b.days?'#e9a1a1':'#c43d3d'}"><title>${esc(b.key)}: ${b.available?fmt(b.total)+' titik terdeteksi':'data tidak tersedia'}</title></rect><rect x="${pad+i*slot}" y="30" width="${slot}" height="166" fill="transparent" tabindex="0" role="button" aria-label="${esc(b.key)}: ${b.available?fmt(b.total)+' titik terdeteksi':'data tidak tersedia'}"><title>${esc(b.key)}: ${b.available?fmt(b.total)+' titik terdeteksi':'data tidak tersedia'}</title></rect>`;if(i%Math.max(1,Math.ceil(series.length/10))===0||i===series.length-1)svg+=`<text x="${x}" y="216">${esc(b.key.slice(5))}</text>`;});$('dailyChart').innerHTML=svg+'</svg><p class="caption">Merah: data tersedia · Merah muda: sebagian hari tersedia · Abu-abu: data belum tersedia. Sentuh atau arahkan kursor ke batang untuk rincian.</p>';
}
for(const id of ['dailyFrom','dailyTo','dailyGran'])$(id).addEventListener('change',renderDaily);
$('refresh').addEventListener('click',loadDaily);loadDaily();setInterval(()=>{if(!document.hidden)loadDaily();},600000);

let dailyResizeTimer;window.addEventListener("resize",()=>{clearTimeout(dailyResizeTimer);dailyResizeTimer=setTimeout(()=>{if(daily.min&&daily.max)renderDaily();},150);});
